    $key=static fn():string=>bin2hex(random_bytes(16));$finance=new Finance($db,$actor);$account=$finance->createAccount('Own real credit refund bank','offline','1000','2025-01-01');$finance->saveAccountSettings($account,0,true,'18000',true,true);$settings=new Settings($db,$actor);
