    $path=$root.'/credit-refund-bank.key';file_put_contents($path,random_bytes(32));chmod($path,0600);$keyHash=hash_file('sha256',$path);putenv('VEREIN_MEMBER_BANK_KEY_PATH='.$path);$vault=new MemberBankVault($db,$actor,$path);$orders=new TransferOrders($db,$actor,$vault);$native=new TransferRequests($db,$actor,$vault);$invoices=new OutgoingInvoices($db,$actor);$bank=['holder'=>'Own saved actual holder '.str_repeat('Ä',100),'iban'=>'DE12500105170648489890','bic'=>'PBNKDEFFXXX'];$today=(new DateTimeImmutable('now',new DateTimeZone('Europe/Berlin')))->format('Y-m-d');$date=(new DateTimeImmutable($today,new DateTimeZone('Europe/Berlin')))->modify('+1 day')->format('Y-m-d');
