    };
    $inputFor=static function(string $entry,string $mode='standard')use($account,$date):array{$today=(new DateTimeImmutable('now',new DateTimeZone('Europe/Berlin')))->format('Y-m-d');$input=TransferInput::initial($entry);$input['data']=array_replace($input['data'],['account'=>$account,'execution_date'=>$mode==='instant'?$today:$date,'purpose'=>'Own original credit refund0 ä🙂','transfer_mode'=>$mode,'reason'=>"Own independently checked credit refund\n0 ä🙂",'evidence'=>'Own actual credit and original invoice']);return $input;};
    return compact('club','actor','reader','foreign','account','path','keyHash','vault','orders','native','invoices','finance','bank','today','date','make','inputFor','root');
